$ErrorActionPreference='Stop'
$projectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../../..'))
$beforeRoot=Join-Path $projectRoot 'docs/development/mask_cpu_preparation_20261024'
$names=@('CG.Emphasis.Present','CG.Mask.Present','CG.Mask.SourceFilter','CG.Mask.BoundsCrop','CG.Mask.CacheLookup','CG.Mask.Output','CG.Mask.QuadUpload','CG.Mask.PageProducer','CG.SpriteReferences.Read','CG.Emphasis.Tint','CG.PhotoShadow.Present','Main Thread','PlayerLoop','GC.Collect','GarbageCollector.CollectIncremental')
$runs=@(foreach($condition in @('before','after')){foreach($rep in 1..3){$path=if($condition -eq 'before'){Join-Path $beforeRoot ('before_'+$rep+'.json')}else{Join-Path $PSScriptRoot ('after_'+$rep+'.json')};if(-not(Test-Path $path)){continue};$data=Get-Content $path -Raw|ConvertFrom-Json;$f=@($data.frames);$metrics=[ordered]@{};foreach($name in $names){$v=@($f|ForEach-Object {$c=$_.counters.$name;if($c.valid -and $null -ne $c.value){[double]$c.value/1e6}}|Sort-Object);$metrics[$name]=@{valid=$v.Count;meanMs=($v|Measure-Object -Average).Average;medianMs=if($v.Count -gt 0){($v[[int][Math]::Floor(($v.Count-1)/2)]+$v[[int][Math]::Floor($v.Count/2)])/2}else{$null}}};$times=@($f.ms|Sort-Object);$sum=($times|Measure-Object -Sum).Sum;$alloc=@($f|ForEach-Object {$_.counters.'GC Allocated In Frame'.value}|Sort-Object);[ordered]@{condition=$condition;rep=$rep;samples=$f.Count;nonunitGaps=@($f|Where-Object {$_.gap -ne 1}).Count;loadMismatch=@($f|Where-Object {$_.enemies -ne 128 -or $_.towers -ne 15}).Count;frameMeanMs=$sum/$f.Count;frameMedianMs=($times[44]+$times[45])/2;frameP95Ms=$times[85];frameMaxMs=$times[-1];fpsMean=$f.Count*1000/$sum;fpsMin=1000/$times[-1];fpsMax=1000/$times[0];drawMean=($f.draw|Measure-Object -Average).Average;setpassMean=($f.setpass|Measure-Object -Average).Average;collections=($f.collectionsSincePrevious|Measure-Object -Sum).Sum;gcMeanBytes=($alloc|Measure-Object -Average).Average;gcMedianBytes=($alloc[44]+$alloc[45])/2;metrics=$metrics}}})
$runs|ConvertTo-Json -Depth 10|Set-Content (Join-Path $PSScriptRoot 'performance_runs.json')
$runs|ForEach-Object {[pscustomobject]@{condition=$_.condition;rep=$_.rep;samples=$_.samples;frameMs=[Math]::Round($_.frameMeanMs,4);maskMs=[Math]::Round($_.metrics['CG.Mask.Present'].meanMs,4);emphasisMs=[Math]::Round($_.metrics['CG.Emphasis.Present'].meanMs,4);boundsMs=[Math]::Round($_.metrics['CG.Mask.BoundsCrop'].meanMs,4);cacheMs=[Math]::Round($_.metrics['CG.Mask.CacheLookup'].meanMs,4);outputMs=[Math]::Round($_.metrics['CG.Mask.Output'].meanMs,4);gc=$_.collections}}|Format-Table -AutoSize
